85	fn escape_data<S: AsRef<str>>(value: S) -> String {
86	    let value = value.as_ref();
87	
88	    // Refs:
89	    // - https://github.com/actions/runner/blob/a4c57f27477077e57545af79851551ff7f5632bd/src/Runner.Common/ActionCommand.cs#L18-L22
90	    // - https://github.com/actions/toolkit/blob/fe3e7ce9a7f995d29d1fcfd226a32bca407f9dc8/packages/core/src/command.ts#L80-L94
91	    let mut result = String::with_capacity(value.len());
92	    for c in value.chars() {
93	        match c {
94	            '\r' => result.push_str("%0D"),
95	            '\n' => result.push_str("%0A"),
96	            '%' => result.push_str("%25"),
97	            _ => result.push(c),
98	        }
99	    }
100	    result
101	}
102	
103	fn escape_property<S: AsRef<str>>(value: S) -> String {
104	    let value = value.as_ref();
105	
106	    // Refs:
107	    // - https://github.com/actions/runner/blob/a4c57f27477077e57545af79851551ff7f5632bd/src/Runner.Common/ActionCommand.cs#L25-L32
108	    // - https://github.com/actions/toolkit/blob/fe3e7ce9a7f995d29d1fcfd226a32bca407f9dc8/packages/core/src/command.ts#L80-L94
109	    let mut result = String::with_capacity(value.len());
110	    for c in value.chars() {
111	        match c {
112	            '\r' => result.push_str("%0D"),
113	            '\n' => result.push_str("%0A"),
114	            ':' => result.push_str("%3A"),
115	            ',' => result.push_str("%2C"),
116	            '%' => result.push_str("%25"),
117	            _ => result.push(c),
118	        }
119	    }
120	    result
121	}
