101	fn escape_property<S: AsRef<str>>(value: S) -> String {
102	    let value = value.as_ref();
103	
104	    // Refs:
105	    // - https://github.com/actions/runner/blob/a4c57f27477077e57545af79851551ff7f5632bd/src/Runner.Common/ActionCommand.cs#L25-L32
106	    // - https://github.com/actions/toolkit/blob/fe3e7ce9a7f995d29d1fcfd226a32bca407f9dc8/packages/core/src/command.ts#L80-L94
107	    let mut result = String::with_capacity(value.len());
108	    for c in value.chars() {
109	        match c {
110	            '\r' => result.push_str("%0D"),
111	            '\n' => result.push_str("%0A"),
112	            ':' => result.push_str("%3A"),
113	            ',' => result.push_str("%2C"),
114	            '%' => result.push_str("%25"),
115	            _ => result.push(c),
116	        }
117	    }
118	    result
119	}
