122	    let mut buffer = Vec::new();
123	    let mut write = fmt::Termcolor(termcolor::NoColor::new(&mut buffer));
124	    let mut fmt = fmt::Formatter::new(&mut write);
125	    fmt.write_markup(markup! { {markup} }).ok()?;
126	    String::from_utf8(buffer).ok()
